private enum class TvSection(val label: String, val icon: ImageVector) {
    HOME("Hem", Icons.Default.Home),
    LIVE("Live TV", Icons.Default.LiveTv),
    MOVIES("Filmer", Icons.Default.Movie),
    SERIES("Serier", Icons.Default.Tv),
