private object TvEngine {
    private val countryMap = mapOf(
        "SE" to "Sverige", "SWE" to "Sverige", "SWEDEN" to "Sverige", "SVERIGE" to "Sverige",
        "NO" to "Norge", "NOR" to "Norge", "NORWAY" to "Norge", "NORGE" to "Norge",
